#include <vector>
#include <fstream>
#include <cstdio>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <cassert>
#include <algorithm>
template<class T>std::vector<T>load(const char*p){std::ifstream f(p,std::ios::ate|std::ios::binary);assert(f);auto n=f.tellg();assert(n>0&&n%sizeof(T)==0);std::vector<T>v(n/sizeof(T));f.seekg(0);f.read((char*)v.data(),n);assert(f);return v;}
bool bits(double a,double b){return memcmp(&a,&b,sizeof(double))==0;}
int main(int argc,char**argv){assert(argc==4);auto fixture=load<float>(argv[1]);auto gold=load<double>(argv[2]);auto a=load<double>(argv[3]);size_t prefix=fixture.size();assert(a.size()==prefix+gold.size());for(size_t i=0;i<prefix;i++)assert(bits(a[i],double(fixture[i])));double maxabs=0,maxbalance=0,maxselected=0;size_t differing=0;for(size_t i=0;i<gold.size();i++){double e=fabs(a[prefix+i]-gold[i]);assert(std::isfinite(a[prefix+i]));assert(e<=2e-4+2e-6*fabs(gold[i]));maxabs=std::max(maxabs,e);}size_t foff=1,off=prefix;printf("{\"cases\":[");for(int ci=0;ci<4;ci++){int n=fixture[foff],z=fixture[foff+1],steps=fixture[foff+2],N=n*n*z,L=N+128;float*q=fixture.data()+foff+3;foff+=11;size_t pin=foff+L;const double*final=a.data()+off,*prev=final+L,*selected=prev+L,*power=selected+L;for(int k=0;k<4;k++){const double*v=final+k*L;for(int j=0;j<64;j++)assert(bits(v[j],-777.)&&bits(v[L-1-j],-777.));}for(int j=0;j<L;j++){assert(bits(power[j],double(fixture[pin+j])));assert(bits(selected[j],steps%2?final[j]:prev[j]));}double sumfinal=0,sumprev=0,sump=0,delta=0;size_t mismatch=0;for(int j=64;j<N+64;j++){sumfinal+=final[j];sumprev+=prev[j];sump+=power[j];if(!bits(final[j],selected[j]))mismatch++;delta=std::max(delta,fabs(final[j]-selected[j]));}double rowsum=double(q[6])+double(q[0])+q[1]+q[2]+q[3]+q[4]+q[5];double predicted=rowsum*sumprev+double(q[7])*sump+double(q[4])*80*N;double residual=fabs(sumfinal-predicted)/std::max(1.,fabs(predicted));assert(residual<=2e-6);maxbalance=std::max(maxbalance,residual);maxselected=std::max(maxselected,delta);differing+=mismatch;printf("%s{\"n\":%d,\"layers\":%d,\"steps\":%d,\"selected_vs_final_differing_values\":%zu,\"selected_vs_final_max_abs\":%.17g,\"last_step_temperature_sum_balance_relative_residual\":%.17g}",ci?",":"",n,z,steps,mismatch,delta,residual);foff+=3*L;off+=4*L;}assert(foff==fixture.size()&&off==a.size());assert(differing>0);printf("],\"all_pass\":true,\"full_values\":%zu,\"input_prefix_bit_exact\":true,\"all_guards_and_readonly_power_bit_exact\":true,\"max_abs_error_against_Float64\":%.17g,\"max_balance_relative_residual\":%.17g,\"known_even_selected_time_level_defect\":true,\"selected_vs_final_total_differing_values\":%zu,\"selected_vs_final_max_abs\":%.17g}\n",a.size(),maxabs,maxbalance,differing,maxselected);}
